/**
 * Unggah berkas pilihan user ke Frappe — dipakai bersama halaman portal.
 *
 * Alurnya dua langkah: `siapkanBerkas` SAAT berkas dipilih, lalu `unggahFile` /
 * `unggahLampiran` saat dikirim (boleh jauh kemudian, mis. saat Simpan).
 */
import { kompresFoto } from './imageCompress'
import { errorMessage } from './toast'

function isGambar(file) {
	return (
		/^image\//.test(file.type || '') ||
		/\.(jpe?g|png|webp|gif|heic|heif)$/i.test(file.name || '')
	)
}

/**
 * Foto diperkecil (lihat kompresFoto), berkas lain dicek ukurannya. Hasilnya selalu
 * berada di memori: berkas dari picker/kamera Android WebView hanya rujukan ke disk
 * dan bisa sudah berubah saat upload baru dijalankan ("Failed to fetch").
 *
 * Melempar Error berpesan siap tampil bila berkas tidak bisa dipakai.
 */
export async function siapkanBerkas(file, { maxMb = 3, label = 'File' } = {}) {
	const maxBytes = maxMb * 1024 * 1024
	let hasil = file
	if (isGambar(file)) {
		hasil = await kompresFoto(file, maxBytes)
		if (!hasil)
			throw new Error(`${label} tidak bisa diperkecil ke ${maxMb} MB. Coba ambil ulang.`)
	} else if (file.size > maxBytes) {
		throw new Error(`Ukuran ${label.toLowerCase()} maksimal ${maxMb} MB.`)
	}
	if (hasil === file) {
		try {
			hasil = new File([await file.arrayBuffer()], file.name, { type: file.type })
		} catch {
			throw new Error(`${label} tidak dapat dibaca, silakan pilih ulang.`)
		}
	}
	return hasil
}

/** POST satu berkas ke method Frappe; resolve `message` dari respons. */
export async function unggahFile(file, { method = 'upload_file', data = {} } = {}) {
	const fd = new FormData()
	fd.append('file', file, file.name)
	for (const [key, value] of Object.entries(data)) {
		if (value != null) fd.append(key, value)
	}
	const res = await fetch(`/api/method/${method}`, {
		method: 'POST',
		credentials: 'include',
		// JANGAN set Content-Type → biar browser pasang boundary multipart.
		headers: { Accept: 'application/json', 'X-Frappe-CSRF-Token': window.csrf_token || '' },
		body: fd,
	})
	const json = await res.json().catch(() => null)
	if (!res.ok) throw new Error((json && errorMessage(json)) || `HTTP ${res.status}`)
	return json?.message
}

/** Unggah ke `upload_file` bawaan sebagai file privat; resolve file_url. */
export async function unggahLampiran(file, uploadDoctype) {
	const message = await unggahFile(file, {
		data: { upload_doctype: uploadDoctype, is_private: 1 },
	})
	if (!message?.file_url) throw new Error('Upload file gagal.')
	return message.file_url
}
